# -*- coding: utf-8 -*-
"""各單元 Part 0 開場「闖關知識地圖」：心怡帶你照邏輯順序走過該單元最常考的四站，
每站＝一張真的數學小圖＋關鍵公式（分數一律標準上下排、根號含上線），看一張圖幾乎抓得到整個單元。
本檔由 _gen_openers.py 產生。"""
import math, random

CHAR_B64 = ""
_F = "font-family=\"'Microsoft JhengHei','PingFang TC','Noto Sans TC','Segoe UI',system-ui,sans-serif\""
MAROON="#8c2740"; ROSE="#b03a5b"; INK="#2b2b2b"; BLUE="#34679a"; GRN="#1f8a5b"; GOLD="#d99a2b"
MUTED="#a87d8e"; CREAM="#fff6f0"; CREAMB="#ecc9c0"; PINK="#fbeef2"; PINKB="#e3c6d0"; AXC="#cdbdc3"
W,H = 720, 432
CW,CH = 244, 156

# ================= 基本零件 =================
def _tw(t,fs):
    w=0.0
    for ch in t:
        if ch==' ': w += fs*0.3
        elif ord(ch)>0x2e80: w += fs*0.96
        else: w += fs*0.55
    return w

def _t(x,y,s,fs=10.0,col=INK,w=False,a="start",it=False):
    s=str(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
    fw=' font-weight="bold"' if w else ''; fi=' font-style="italic"' if it else ''
    return f'<text x="{x:.1f}" y="{y:.1f}" font-size="{fs}"{fw}{fi} fill="{col}" text-anchor="{a}">{s}</text>'

def _num(cx,cy,n):
    return (f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="12" fill="#fff"/><circle cx="{cx:.1f}" cy="{cy:.1f}" r="11" fill="{MAROON}"/>'
            f'<text x="{cx:.1f}" y="{cy+4.6:.1f}" font-size="13" font-weight="bold" fill="#fff" text-anchor="middle">{n}</text>')

def _pill(cx,cy,w,text,fill=MAROON,fg="#fff",fs=10.5):
    return (f'<rect x="{cx-w/2:.0f}" y="{cy-9:.0f}" width="{w}" height="18" rx="9" fill="{fill}"/>'
            f'<text x="{cx:.0f}" y="{cy+4:.0f}" font-size="{fs}" font-weight="bold" fill="{fg}" text-anchor="middle">{text}</text>')

def _stars(cx,cy,n):
    s=9.5
    return "".join(f'<text x="{cx-(n-1)*s/2+i*s:.1f}" y="{cy}" font-size="11" fill="{GOLD}" text-anchor="middle">★</text>' for i in range(n))

def _trail(x1,y1,x2,y2,cxp,cyp,col=MAROON):
    p=(f'<path d="M{x1:.1f},{y1:.1f} Q{cxp:.1f},{cyp:.1f} {x2:.1f},{y2:.1f}" fill="none" '
       f'stroke="{col}" stroke-width="2.6" stroke-linecap="round" stroke-dasharray="1.5 6" opacity="0.8"/>')
    ang=math.atan2(y2-cyp,x2-cxp); s=9
    h1=(x2+s*math.cos(ang+math.radians(150)), y2+s*math.sin(ang+math.radians(150)))
    h2=(x2+s*math.cos(ang-math.radians(150)), y2+s*math.sin(ang-math.radians(150)))
    return p+f'<polygon points="{x2:.1f},{y2:.1f} {h1[0]:.1f},{h1[1]:.1f} {h2[0]:.1f},{h2[1]:.1f}" fill="{col}"/>'

# 完整根號：√鉤＋上線蓋住被開方式，回傳 (svg, 寬度)
def _sqrt(x, yb, inner, fs=10, col=INK, bold=False):
    iw=_tw(inner,fs); lead=fs*0.64; top=yb-fs*0.96; barx2=x+lead+iw+3
    hook=(f'<path d="M{x:.1f},{yb-fs*0.30:.1f} L{x+fs*0.22:.1f},{yb+1.5:.1f} '
          f'L{x+lead-1:.1f},{top:.1f} L{barx2:.1f},{top:.1f}" fill="none" stroke="{col}" '
          f'stroke-width="1.2" stroke-linejoin="round" stroke-linecap="round"/>')
    return hook+_t(x+lead+1,yb,inner,fs,col,w=bold), barx2-x

# 標準矩陣：方括弧＋分行分列排，回傳 (svg, 寬度)
def _matrix(x, ymid, rows, fs=10, col=INK, bold=False):
    nr=len(rows); nc=len(rows[0])
    colw=[max(_tw(rows[i][j],fs) for i in range(nr)) for j in range(nc)]
    colgap=7.0; rh=fs*1.4; bw=4.0; gap=3.5
    contentw=sum(colw)+colgap*(nc-1); totalw=bw+gap+contentw+gap+bw
    Hh=nr*rh; top=ymid-Hh/2; bot=ymid+Hh/2; rx=x+totalw
    out=[f'<path d="M{x+bw:.1f},{top:.1f} L{x:.1f},{top:.1f} L{x:.1f},{bot:.1f} L{x+bw:.1f},{bot:.1f}" fill="none" stroke="{col}" stroke-width="1.1"/>',
         f'<path d="M{rx-bw:.1f},{top:.1f} L{rx:.1f},{top:.1f} L{rx:.1f},{bot:.1f} L{rx-bw:.1f},{bot:.1f}" fill="none" stroke="{col}" stroke-width="1.1"/>']
    cx0=x+bw+gap
    for j in range(nc):
        ccx=cx0+sum(colw[:j])+colgap*j+colw[j]/2
        for i in range(nr):
            out.append(_t(ccx, top+rh*(i+0.5)+fs*0.34, rows[i][j], fs, col, w=bold, a="middle"))
    return "".join(out), totalw

# 行內數學排版（遞迴）：tokens 元素＝
#   ("t",字串) 文字 / ("s",被開方式) 完整根號 / ("b",字母) 上線(平均) /
#   ("f",分子字串,分母字串) 簡單分數 / ("st",分子tokens,分母tokens) 一般分數(可含根號)
# 回傳 (svg, 寬度)。x 為起點、ymid 為分數線中心高。
def _inline(x, ymid, tokens, fs=10, col=INK, bold=False):
    cur=x; out=[]; yb=ymid+fs*0.34
    def frac(num,den):
        nonlocal cur
        _,nw=_inline(0,0,num,fs,col,bold); _,dw=_inline(0,0,den,fs,col,bold)
        bw=max(nw,dw)+6
        ns,_=_inline(cur+(bw-nw)/2, ymid-fs*0.62, num, fs, col, bold)
        ds,_=_inline(cur+(bw-dw)/2, ymid+fs*0.56, den, fs, col, bold)
        out.append(ns); out.append(f'<line x1="{cur:.1f}" y1="{ymid:.1f}" x2="{cur+bw:.1f}" y2="{ymid:.1f}" stroke="{col}" stroke-width="1"/>'); out.append(ds)
        cur+=bw+2.5
    for tok in tokens:
        k=tok[0]
        if k=="t": out.append(_t(cur,yb,tok[1],fs,col,w=bold)); cur+=_tw(tok[1],fs)+1.5
        elif k=="s": sv,sw=_sqrt(cur,yb,tok[1],fs,col,bold); out.append(sv); cur+=sw+2
        elif k=="b":
            ww=_tw(tok[1],fs); out.append(_t(cur,yb,tok[1],fs,col,w=bold))
            out.append(f'<line x1="{cur:.1f}" y1="{yb-fs*0.92:.1f}" x2="{cur+ww:.1f}" y2="{yb-fs*0.92:.1f}" stroke="{col}" stroke-width="1"/>'); cur+=ww+1.5
        elif k=="v":  # 向量符號：字母上加右箭頭
            s=tok[1]; ww=_tw(s,fs); out.append(_t(cur,yb,s,fs,col,w=bold)); ay=yb-fs*0.95
            out.append(f'<line x1="{cur:.1f}" y1="{ay:.1f}" x2="{cur+ww:.1f}" y2="{ay:.1f}" stroke="{col}" stroke-width="0.9"/>')
            out.append(f'<polygon points="{cur+ww+1.5:.1f},{ay:.1f} {cur+ww-1.5:.1f},{ay-1.7:.1f} {cur+ww-1.5:.1f},{ay+1.7:.1f}" fill="{col}"/>')
            cur+=ww+1.5
        elif k=="f": frac([("t",tok[1])],[("t",tok[2])])
        elif k=="st": frac(tok[1],tok[2])
        elif k=="m":
            mv,mw=_matrix(cur,ymid,tok[1],fs,col,bold); out.append(mv); cur+=mw+2.5
    return "".join(out), cur-x

def _row(x, ymid, tokens, fs=10, hi=False):
    return _inline(x,ymid,tokens,fs,ROSE if hi else INK,hi)[0]

def _sinelaw(x, ymid, fs=10):
    s,w=_inline(x,ymid,[("f","a","sinA"),("t","="),("f","b","sinB"),("t","="),("f","c","sinC"),("t","=")],fs,INK,False)
    return s+_t(x+w+1,ymid+fs*0.34,"2R",fs,ROSE,w=True)

# ================= 角色＋對話框 =================
def _char(x,y,w,h):
    return f'<image x="{x}" y="{y}" width="{w}" height="{h}" href="data:image/png;base64,{CHAR_B64}"/>'

def _bubble(cx,cy,w,text):
    return (f'<rect x="{cx-w/2:.0f}" y="{cy-15:.0f}" width="{w}" height="30" rx="14" fill="#fff" stroke="{ROSE}" stroke-width="1.6"/>'
            f'<polygon points="{cx-w/2+10:.0f},{cy+13:.0f} {cx-w/2+4:.0f},{cy+26:.0f} {cx-w/2+24:.0f},{cy+14:.0f}" fill="#fff" stroke="{ROSE}" stroke-width="1.6"/>'
            f'<polygon points="{cx-w/2+11:.0f},{cy+14:.0f} {cx-w/2+22:.0f},{cy+14:.0f} {cx-w/2+6:.0f},{cy+24:.0f}" fill="#fff"/>'
            f'<text x="{cx:.0f}" y="{cy+5:.0f}" font-size="13" font-weight="bold" fill="{ROSE}" text-anchor="middle">{text}</text>')

# ================= 小圖共用 =================
def _axn(cx,cy,R,xr=0.95,yr=0.95):
    return (f'<line x1="{cx-R*xr:.1f}" y1="{cy}" x2="{cx+R*xr:.1f}" y2="{cy}" stroke="{AXC}" stroke-width="1"/>'
            f'<line x1="{cx}" y1="{cy+R*yr:.1f}" x2="{cx}" y2="{cy-R*yr:.1f}" stroke="{AXC}" stroke-width="1"/>')

def _vec(p,q,col):
    ang=math.atan2(q[1]-p[1],q[0]-p[0]); s=6
    h1=(q[0]-s*math.cos(ang-0.42),q[1]-s*math.sin(ang-0.42)); h2=(q[0]-s*math.cos(ang+0.42),q[1]-s*math.sin(ang+0.42))
    return (f'<line x1="{p[0]:.1f}" y1="{p[1]:.1f}" x2="{q[0]:.1f}" y2="{q[1]:.1f}" stroke="{col}" stroke-width="1.8"/>'
            f'<polygon points="{q[0]:.1f},{q[1]:.1f} {h1[0]:.1f},{h1[1]:.1f} {h2[0]:.1f},{h2[1]:.1f}" fill="{col}"/>')

# ====== 三角四站小圖 ======
def _mf_unit(cx,cy,R):
    a=math.radians(54); px=cx+R*0.82*math.cos(a); py=cy-R*0.82*math.sin(a)
    return _axn(cx,cy,R)+"".join([
        f'<circle cx="{cx}" cy="{cy}" r="{R*0.82:.1f}" fill="none" stroke="{BLUE}" stroke-width="1.6"/>',
        f'<line x1="{cx}" y1="{cy}" x2="{px:.1f}" y2="{py:.1f}" stroke="{ROSE}" stroke-width="1.9"/>',
        f'<line x1="{px:.1f}" y1="{py:.1f}" x2="{px:.1f}" y2="{cy}" stroke="{GRN}" stroke-width="1.7"/>',
        f'<circle cx="{px:.1f}" cy="{py:.1f}" r="2.6" fill="{MAROON}"/>'])
def _mf_tri(cx,cy,R):
    pts=[(cx+R*0.85*math.cos(math.radians(d)), cy+R*0.85*math.sin(math.radians(d))) for d in (-90,150,30)]
    poly=" ".join(f"{x:.1f},{y:.1f}" for x,y in pts)
    return "".join([f'<circle cx="{cx}" cy="{cy}" r="{R*0.85:.1f}" fill="none" stroke="#9fbdd7" stroke-width="1.3"/>',
        f'<polygon points="{poly}" fill="#f6e3d9" fill-opacity="0.55" stroke="{INK}" stroke-width="1.7" stroke-linejoin="round"/>',
        f'<circle cx="{cx}" cy="{cy}" r="1.8" fill="{ROSE}"/>'])
def _wave(cx,cy,R,amp,ph,col,wd,per=1.25):
    pts=[f"{cx-R*0.95+1.9*R*i/40:.1f},{cy-amp*math.sin(2*math.pi*per*(i/40)+ph):.1f}" for i in range(41)]
    return f'<polyline points="{" ".join(pts)}" fill="none" stroke="{col}" stroke-width="{wd}" stroke-linecap="round" stroke-linejoin="round"/>'
def _mf_sine(cx,cy,R): return _axn(cx,cy,R,0.95,0.6)+_wave(cx,cy,R,R*0.52,0,ROSE,2.1)
def _mf_super(cx,cy,R):
    return (_axn(cx,cy,R,0.95,0.6)+_wave(cx,cy,R,R*0.30,0,"#86b496",1.3,1)+_wave(cx,cy,R,R*0.30,1.7,"#9fbdd7",1.3,1)+_wave(cx,cy,R,R*0.54,0.7,MAROON,2.2,1))

# ====== 機率 ======
def _mf_perm(cx,cy,R):
    w=R*0.5; x0=cx-1.5*w; g=[]
    for i in range(3):
        g.append(f'<rect x="{x0+i*w:.1f}" y="{cy-w*0.5:.1f}" width="{w-3:.1f}" height="{w:.1f}" rx="2" fill="#f6e3d9" stroke="{MAROON}" stroke-width="1.2"/>')
        g.append(_t(x0+i*w+(w-3)/2,cy+3,str(i+1),8,MAROON,a="middle"))
    g.append(_t(cx,cy-w*0.95,"順序",8.5,ROSE,a="middle"))
    return "".join(g)
def _mf_comb(cx,cy,R):
    g=[f'<ellipse cx="{cx}" cy="{cy}" rx="{R*0.95:.1f}" ry="{R*0.72:.1f}" fill="#f6e3d9" fill-opacity="0.4" stroke="{BLUE}" stroke-width="1.3"/>']
    for i,(dx,dy) in enumerate([(-0.5,-0.2),(0,-0.3),(0.5,-0.15),(-0.3,0.32),(0.32,0.3)]):
        g.append(f'<circle cx="{cx+dx*R:.1f}" cy="{cy+dy*R:.1f}" r="3.2" fill="{MAROON if i<3 else "#fff"}" stroke="{MAROON}" stroke-width="1.1"/>')
    return "".join(g)
def _mf_dice(cx,cy,R):
    s=R*1.3; x=cx-s/2; y=cy-s/2
    g=[f'<rect x="{x:.1f}" y="{y:.1f}" width="{s:.1f}" height="{s:.1f}" rx="{s*0.18:.1f}" fill="#fff" stroke="{MAROON}" stroke-width="1.6"/>']
    for px,py in [(0.25,0.25),(0.75,0.25),(0.5,0.5),(0.25,0.75),(0.75,0.75)]:
        g.append(f'<circle cx="{x+px*s:.1f}" cy="{y+py*s:.1f}" r="{s*0.07:.1f}" fill="{MAROON}"/>')
    return "".join(g)
def _mf_tree(cx,cy,R):
    n0=(cx-R*0.85,cy); a=(cx+R*0.1,cy-R*0.6); b=(cx+R*0.1,cy+R*0.6)
    leaves=[(cx+R*0.95,cy-R*0.85),(cx+R*0.95,cy-R*0.35),(cx+R*0.95,cy+R*0.35),(cx+R*0.95,cy+R*0.85)]
    seg=lambda p,q:f'<line x1="{p[0]:.1f}" y1="{p[1]:.1f}" x2="{q[0]:.1f}" y2="{q[1]:.1f}" stroke="{MAROON}" stroke-width="1.2"/>'
    g=[seg(n0,a),seg(n0,b),seg(a,leaves[0]),seg(a,leaves[1]),seg(b,leaves[2]),seg(b,leaves[3])]
    for p in (n0,a,b): g.append(f'<circle cx="{p[0]:.1f}" cy="{p[1]:.1f}" r="2.4" fill="{MAROON}"/>')
    for p in leaves: g.append(f'<circle cx="{p[0]:.1f}" cy="{p[1]:.1f}" r="2" fill="{ROSE}"/>')
    return "".join(g)

# ====== 空間向量 ======
def _mf_axes3(cx,cy,R):
    g=[f'<line x1="{cx}" y1="{cy+R*0.7:.1f}" x2="{cx}" y2="{cy-R*0.9:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>',
       f'<line x1="{cx}" y1="{cy}" x2="{cx+R*0.95:.1f}" y2="{cy+R*0.4:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>',
       f'<line x1="{cx}" y1="{cy}" x2="{cx-R*0.85:.1f}" y2="{cy+R*0.5:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>',
       _vec((cx,cy),(cx+R*0.5,cy-R*0.6),ROSE),
       f'<circle cx="{cx+R*0.5:.1f}" cy="{cy-R*0.6:.1f}" r="2.4" fill="{MAROON}"/>']
    return "".join(g)
def _mf_vecang(cx,cy,R):
    o=(cx-R*0.45,cy+R*0.45)
    g=[_vec(o,(o[0]+R*1.05,o[1]-R*0.15),MAROON),_vec(o,(o[0]+R*0.45,o[1]-R*1.0),BLUE)]
    g.append(f'<path d="M{o[0]+20:.1f},{o[1]-4:.1f} A 20 20 0 0 0 {o[0]+9:.1f},{o[1]-18:.1f}" fill="none" stroke="{ROSE}" stroke-width="1.1"/>')
    return "".join(g)
def _mf_cross(cx,cy,R):
    o=(cx-R*0.5,cy+R*0.45); p2=(o[0]+R*1.0,o[1]-R*0.15); p4=(o[0]+R*0.45,o[1]-R*0.9); p3=(p2[0]+R*0.45,p2[1]-R*0.9)
    return (f'<polygon points="{o[0]:.1f},{o[1]:.1f} {p2[0]:.1f},{p2[1]:.1f} {p3[0]:.1f},{p3[1]:.1f} {p4[0]:.1f},{p4[1]:.1f}" fill="#f6e3d9" fill-opacity="0.5" stroke="{INK}" stroke-width="1.3"/>'
            +_vec(o,p2,MAROON)+_vec(o,p4,BLUE))
def _mf_plane(cx,cy,R):
    p1=(cx-R*0.9,cy+R*0.12);p2=(cx-R*0.1,cy+R*0.55);p3=(cx+R*0.9,cy-R*0.12);p4=(cx+R*0.1,cy-R*0.55)
    pt=(cx+R*0.05,cy-R*0.78)
    return (f'<polygon points="{p1[0]:.1f},{p1[1]:.1f} {p2[0]:.1f},{p2[1]:.1f} {p3[0]:.1f},{p3[1]:.1f} {p4[0]:.1f},{p4[1]:.1f}" fill="#e7eef6" stroke="{BLUE}" stroke-width="1.2"/>'
            f'<line x1="{pt[0]:.1f}" y1="{pt[1]:.1f}" x2="{cx:.1f}" y2="{cy:.1f}" stroke="{ROSE}" stroke-width="1.4" stroke-dasharray="2 2"/>'
            f'<circle cx="{pt[0]:.1f}" cy="{pt[1]:.1f}" r="2.6" fill="{MAROON}"/>')

# ====== 多項式 ======
def _mf_div(cx,cy,R):  # 長除式：左 ) 括弧＋上線，被除式 f(x) 在右下
    bx=cx-R*0.55; ty=cy-R*0.5; by=cy+R*0.5
    return (f'<path d="M{bx:.1f},{ty:.1f} Q{bx+R*0.4:.1f},{cy:.1f} {bx:.1f},{by:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.6"/>'
            f'<path d="M{bx:.1f},{ty:.1f} L{cx+R*0.85:.1f},{ty:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.6"/>'
            +_t(cx+R*0.34,cy+R*0.12,"f(x)",8.5,INK,a="middle"))
def _mf_parab(cx,cy,R):
    pts=[f"{cx+(-1+2*i/20)*R*0.9:.1f},{cy+R*0.5-((-1+2*i/20)**2)*R*1.1:.1f}" for i in range(21)]
    return _axn(cx,cy,R)+f'<polyline points="{" ".join(pts)}" fill="none" stroke="{MAROON}" stroke-width="2"/>'+f'<circle cx="{cx:.1f}" cy="{cy+R*0.5:.1f}" r="2.4" fill="{ROSE}"/>'
def _mf_signline(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy}" x2="{cx+R:.1f}" y2="{cy}" stroke="#9aa6b2" stroke-width="1.4"/>']
    for rx in (-R*0.45,R*0.45): g.append(f'<circle cx="{cx+rx:.1f}" cy="{cy}" r="2.6" fill="#fff" stroke="{MAROON}" stroke-width="1.4"/>')
    g+=[_t(cx-R*0.75,cy-4,"+",10,GRN,a="middle"),_t(cx,cy-4,"−",10,ROSE,a="middle"),_t(cx+R*0.75,cy-4,"+",10,GRN,a="middle")]
    return "".join(g)
def _mf_cubic(cx,cy,R):
    pts=[f"{cx+(-1.2+2.4*i/30)*R*0.78:.1f},{cy-((-1.2+2.4*i/30)**3-1.2*(-1.2+2.4*i/30))*R*0.42:.1f}" for i in range(31)]
    return _axn(cx,cy,R)+f'<polyline points="{" ".join(pts)}" fill="none" stroke="{MAROON}" stroke-width="2"/>'+f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="2.4" fill="{ROSE}"/>'

# ====== 直線與圓 ======
def _mf_slope(cx,cy,R):
    a=(cx-R*0.85,cy+R*0.6); b=(cx+R*0.85,cy-R*0.7); c=(b[0],a[1])
    return (f'<line x1="{a[0]:.1f}" y1="{a[1]:.1f}" x2="{b[0]:.1f}" y2="{b[1]:.1f}" stroke="{MAROON}" stroke-width="2"/>'
            f'<line x1="{a[0]:.1f}" y1="{a[1]:.1f}" x2="{c[0]:.1f}" y2="{c[1]:.1f}" stroke="{BLUE}" stroke-width="1.2" stroke-dasharray="2 2"/>'
            f'<line x1="{c[0]:.1f}" y1="{c[1]:.1f}" x2="{b[0]:.1f}" y2="{b[1]:.1f}" stroke="{GRN}" stroke-width="1.2" stroke-dasharray="2 2"/>')
def _mf_dist2(cx,cy,R):
    a=(cx-R*0.6,cy+R*0.5); b=(cx+R*0.6,cy-R*0.5)
    return (f'<line x1="{a[0]:.1f}" y1="{a[1]:.1f}" x2="{b[0]:.1f}" y2="{b[1]:.1f}" stroke="{ROSE}" stroke-width="1.6" stroke-dasharray="3 2"/>'
            f'<circle cx="{a[0]:.1f}" cy="{a[1]:.1f}" r="2.8" fill="{MAROON}"/><circle cx="{b[0]:.1f}" cy="{b[1]:.1f}" r="2.8" fill="{MAROON}"/>')
def _mf_circle(cx,cy,R):
    return (_axn(cx,cy,R)+f'<circle cx="{cx}" cy="{cy}" r="{R*0.7:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.8"/>'
            f'<line x1="{cx}" y1="{cy}" x2="{cx+R*0.7:.1f}" y2="{cy}" stroke="{ROSE}" stroke-width="1.4"/><circle cx="{cx}" cy="{cy}" r="2" fill="{MAROON}"/>')
def _mf_tangent(cx,cy,R):
    return (f'<circle cx="{cx}" cy="{cy}" r="{R*0.62:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.6"/>'
            f'<line x1="{cx-R:.1f}" y1="{cy-R*0.62:.1f}" x2="{cx+R:.1f}" y2="{cy-R*0.62:.1f}" stroke="{ROSE}" stroke-width="1.6"/>'
            f'<line x1="{cx-R*0.5:.1f}" y1="{cy+R*0.37:.1f}" x2="{cx+R*0.5:.1f}" y2="{cy+R*0.37:.1f}" stroke="{BLUE}" stroke-width="1.4"/>'
            f'<circle cx="{cx}" cy="{cy-R*0.62:.1f}" r="1.8" fill="{MAROON}"/>')

# ====== 指對數 ======
def _axes_o(ox,oy,xl,xr,yt,yb):
    return (f'<line x1="{ox-xl:.1f}" y1="{oy:.1f}" x2="{ox+xr:.1f}" y2="{oy:.1f}" stroke="#9aa6b2" stroke-width="1"/>'
            f'<line x1="{ox:.1f}" y1="{oy+yb:.1f}" x2="{ox:.1f}" y2="{oy-yt:.1f}" stroke="#9aa6b2" stroke-width="1"/>')
def _mf_exp(cx,cy,R):  # y=2^x 必過 (0,1)
    ox=cx-R*0.5; oy=cy+R*0.62; u=R*0.5; pts=[]
    for i in range(41):
        x=-1.3+2.7*i/40; y=2**x
        if y>2.6: break
        pts.append(f"{ox+x*u:.1f},{oy-y*u:.1f}")
    return (_axes_o(ox,oy,R*0.4,R*1.35,R*1.45,R*0.32)+f'<polyline points="{" ".join(pts)}" fill="none" stroke="{MAROON}" stroke-width="2"/>'
            +f'<circle cx="{ox:.1f}" cy="{oy-u:.1f}" r="2.4" fill="{ROSE}"/>'+_t(ox-3,oy-u-2,"(0,1)",6.5,ROSE,a="end"))
def _mf_log(cx,cy,R):  # y=log₂x 必過 (1,0)
    ox=cx-R*0.55; oy=cy+R*0.08; u=R*0.5; pts=[]
    for i in range(41):
        x=0.3+2.5*i/40; y=math.log(x,2)
        pts.append(f"{ox+x*u:.1f},{oy-y*u:.1f}")
    return (_axes_o(ox,oy,R*0.25,R*1.45,R*0.92,R*0.92)+f'<polyline points="{" ".join(pts)}" fill="none" stroke="{BLUE}" stroke-width="2"/>'
            +f'<circle cx="{ox+u:.1f}" cy="{oy:.1f}" r="2.4" fill="{ROSE}"/>'+_t(ox+u,oy+9,"(1,0)",6.5,ROSE,a="middle"))
def _mf_digits(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy+R*0.5:.1f}" x2="{cx+R:.1f}" y2="{cy+R*0.5:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>']
    for i,lab in enumerate(["1","10","10²"]):
        x=cx-R*0.7+i*R*0.7
        g.append(f'<line x1="{x:.1f}" y1="{cy+R*0.5:.1f}" x2="{x:.1f}" y2="{cy+R*0.5-(i+1)*R*0.34:.1f}" stroke="{MAROON}" stroke-width="2"/>')
        g.append(_t(x,cy+R*0.78,lab,7,INK,a="middle"))
    return "".join(g)
def _mf_symlog(cx,cy,R):  # y=aˣ 與 y=logₐx 對稱於 y=x（指過(0,1)、對數過(1,0)）
    ox=cx-R*0.42; oy=cy+R*0.42; u=R*0.42
    g=[_axes_o(ox,oy,R*0.45,R*1.3,R*1.3,R*0.55)]
    g.append(f'<line x1="{ox-R*0.5:.1f}" y1="{oy+R*0.5:.1f}" x2="{ox+R*1.25:.1f}" y2="{oy-R*1.25:.1f}" stroke="{AXC}" stroke-width="1" stroke-dasharray="3 2"/>')
    em=[]
    for i in range(41):
        x=-1.3+2.7*i/40; y=2**x
        if y>2.5: break
        em.append((x,y))
    g.append(f'<polyline points="{" ".join(f"{ox+x*u:.1f},{oy-y*u:.1f}" for x,y in em)}" fill="none" stroke="{MAROON}" stroke-width="1.7"/>')
    g.append(f'<polyline points="{" ".join(f"{ox+y*u:.1f},{oy-x*u:.1f}" for x,y in em)}" fill="none" stroke="{BLUE}" stroke-width="1.7"/>')
    g.append(f'<circle cx="{ox:.1f}" cy="{oy-u:.1f}" r="2.1" fill="{MAROON}"/><circle cx="{ox+u:.1f}" cy="{oy:.1f}" r="2.1" fill="{BLUE}"/>')
    g.append(_t(ox+R*1.16,oy-R*1.16,"y=x",6,MUTED,a="middle"))
    return "".join(g)

# ====== 平面向量 ======
def _mf_vadd(cx,cy,R):  # 向量 a=(a₁,a₂)＋分量
    o=(cx-R*0.55,cy+R*0.5); tip=(o[0]+R*1.05,o[1]-R*0.95); foot=(tip[0],o[1])
    return (f'<line x1="{o[0]:.1f}" y1="{o[1]:.1f}" x2="{foot[0]:.1f}" y2="{o[1]:.1f}" stroke="#9fbdd7" stroke-width="1.2" stroke-dasharray="2 2"/>'
            f'<line x1="{foot[0]:.1f}" y1="{o[1]:.1f}" x2="{tip[0]:.1f}" y2="{tip[1]:.1f}" stroke="{GRN}" stroke-width="1.2" stroke-dasharray="2 2"/>'
            +_vec(o,tip,MAROON)
            +_t((o[0]+foot[0])/2, o[1]+8, "a₁",6,BLUE,a="middle")
            +_t(foot[0]+7, (o[1]+tip[1])/2+2, "a₂",6,GRN,a="middle"))
def _mf_divpt(cx,cy,R):
    a=(cx-R*0.9,cy+R*0.35); b=(cx+R*0.9,cy-R*0.35); p=(a[0]+(b[0]-a[0])*0.62,a[1]+(b[1]-a[1])*0.62)
    return (f'<line x1="{a[0]:.1f}" y1="{a[1]:.1f}" x2="{b[0]:.1f}" y2="{b[1]:.1f}" stroke="{MAROON}" stroke-width="1.6"/>'
            f'<circle cx="{a[0]:.1f}" cy="{a[1]:.1f}" r="2.4" fill="{MAROON}"/><circle cx="{b[0]:.1f}" cy="{b[1]:.1f}" r="2.4" fill="{MAROON}"/>'
            f'<circle cx="{p[0]:.1f}" cy="{p[1]:.1f}" r="2.8" fill="{ROSE}"/>')
def _mf_proj(cx,cy,R):
    o=(cx-R*0.7,cy+R*0.45); a=(o[0]+R*1.45,o[1]); b=(o[0]+R*0.75,o[1]-R*0.85); foot=(b[0],o[1])
    return (_vec(o,a,BLUE)+_vec(o,b,MAROON)
            +f'<line x1="{b[0]:.1f}" y1="{b[1]:.1f}" x2="{foot[0]:.1f}" y2="{foot[1]:.1f}" stroke="{ROSE}" stroke-width="1.2" stroke-dasharray="2 2"/>'
            +_vec(o,foot,GRN))
def _mf_para(cx,cy,R):
    o=(cx-R*0.6,cy+R*0.45); p2=(o[0]+R*1.05,o[1]-R*0.1); p4=(o[0]+R*0.4,o[1]-R*0.85); p3=(p2[0]+R*0.4,p2[1]-R*0.85)
    return (f'<polygon points="{o[0]:.1f},{o[1]:.1f} {p2[0]:.1f},{p2[1]:.1f} {p3[0]:.1f},{p3[1]:.1f} {p4[0]:.1f},{p4[1]:.1f}" fill="#f6e3d9" fill-opacity="0.5" stroke="{MAROON}" stroke-width="1.4"/>'
            +_vec(o,p2,MAROON)+_vec(o,p4,BLUE))

# ====== 數據分析 ======
def _mf_spread(cx,cy,R):
    oy=cy+R*0.28; dy=oy-R*0.42
    g=[f'<line x1="{cx-R:.1f}" y1="{oy:.1f}" x2="{cx+R:.1f}" y2="{oy:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>',
       f'<line x1="{cx:.1f}" y1="{oy-R*0.82:.1f}" x2="{cx:.1f}" y2="{oy+R*0.16:.1f}" stroke="{ROSE}" stroke-width="1.4" stroke-dasharray="2 2"/>',
       _t(cx,oy+R*0.62,"平均",6.5,ROSE,a="middle")]
    for dx in (-0.78,-0.5,-0.22,0.18,0.45,0.82): g.append(f'<circle cx="{cx+dx*R:.1f}" cy="{dy:.1f}" r="2.2" fill="#2c7a7b"/>')
    tx=cx+0.7*R; ay=dy-R*0.32
    g.append(f'<line x1="{cx:.1f}" y1="{ay:.1f}" x2="{tx:.1f}" y2="{ay:.1f}" stroke="{MAROON}" stroke-width="1"/>')
    g.append(f'<polygon points="{tx:.1f},{ay:.1f} {tx-4:.1f},{ay-2.2:.1f} {tx-4:.1f},{ay+2.2:.1f}" fill="{MAROON}"/>')
    g.append(f'<polygon points="{cx:.1f},{ay:.1f} {cx+4:.1f},{ay-2.2:.1f} {cx+4:.1f},{ay+2.2:.1f}" fill="{MAROON}"/>')
    g.append(_t((cx+tx)/2,ay-2.3,"離差",6.5,MAROON,a="middle"))
    return "".join(g)
def _mf_scatpos(cx,cy,R):
    random.seed(5); g=[_axn(cx,cy,R)]
    for i in range(9):
        t=i/8; g.append(f'<circle cx="{cx-R*0.8+1.6*R*t:.1f}" cy="{cy+R*0.6-1.2*R*t+random.uniform(-0.12,0.12)*R:.1f}" r="2.1" fill="#2c7a7b"/>')
    return "".join(g)
def _mf_regline(cx,cy,R):
    return _mf_scatpos(cx,cy,R)+f'<line x1="{cx-R*0.8:.1f}" y1="{cy+R*0.55:.1f}" x2="{cx+R*0.8:.1f}" y2="{cy-R*0.6:.1f}" stroke="{ROSE}" stroke-width="1.8"/>'
def _mf_wbar(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy+R*0.6:.1f}" x2="{cx+R:.1f}" y2="{cy+R*0.6:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>']
    for i,h in enumerate([0.5,1.0,0.7,1.25]):
        x=cx-R*0.75+i*R*0.5
        g.append(f'<rect x="{x:.1f}" y="{cy+R*0.6-h*R:.1f}" width="{R*0.32:.1f}" height="{h*R:.1f}" fill="#f1d6df" stroke="{MAROON}" stroke-width="1.1"/>')
    return "".join(g)

# ====== 數列 ======
def _mf_arith(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy+R*0.6:.1f}" x2="{cx+R:.1f}" y2="{cy+R*0.6:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>']
    for i in range(4):
        x=cx-R*0.75+i*R*0.5; h=(i+1)*R*0.27
        if i: g.append(f'<line x1="{cx-R*0.75+(i-1)*R*0.5:.1f}" y1="{cy+R*0.6-i*R*0.27:.1f}" x2="{x:.1f}" y2="{cy+R*0.6-h:.1f}" stroke="{ROSE}" stroke-width="1.1"/>')
        g.append(f'<circle cx="{x:.1f}" cy="{cy+R*0.6-h:.1f}" r="2.6" fill="{MAROON}"/>')
    return "".join(g)
def _mf_geom(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy+R*0.6:.1f}" x2="{cx+R:.1f}" y2="{cy+R*0.6:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>']
    for i in range(4):
        x=cx-R*0.75+i*R*0.5; h=(1.65**i)*R*0.17
        g.append(f'<circle cx="{x:.1f}" cy="{cy+R*0.6-h:.1f}" r="2.6" fill="{MAROON}"/>')
    return "".join(g)
def _mf_recur(cx,cy,R):
    xs=[cx-R*0.7,cx,cx+R*0.7]; g=[f'<circle cx="{x:.1f}" cy="{cy+R*0.25:.1f}" r="2.6" fill="{MAROON}"/>' for x in xs]
    for i in range(2):
        g.append(f'<path d="M{xs[i]:.1f},{cy+R*0.1:.1f} q {R*0.35:.1f},{-R*0.55:.1f} {R*0.7:.1f},0" fill="none" stroke="{ROSE}" stroke-width="1.3"/>')
        g.append(f'<polygon points="{xs[i+1]:.1f},{cy+R*0.1:.1f} {xs[i+1]-5:.1f},{cy:.1f} {xs[i+1]-1:.1f},{cy+R*0.16:.1f}" fill="{ROSE}"/>')
    return "".join(g)
def _mf_sigma(cx,cy,R):
    g=[_t(cx-R*0.5,cy+R*0.45,"Σ",R*1.5,MAROON,w=True,a="middle")]
    for i in range(3):
        x=cx+R*0.15+i*R*0.34; h=(i+1.5)*R*0.22
        g.append(f'<rect x="{x:.1f}" y="{cy+R*0.45-h:.1f}" width="{R*0.24:.1f}" height="{h:.1f}" fill="#f1d6df" stroke="{MAROON}" stroke-width="1"/>')
    return "".join(g)

# ====== 矩陣 ======
def _mf_mat(cx,cy,R):
    w=R*1.2;h=R*1.1;x=cx-w/2;y=cy-h/2
    g=[f'<path d="M{x+4:.1f},{y:.1f} L{x:.1f},{y:.1f} L{x:.1f},{y+h:.1f} L{x+4:.1f},{y+h:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.5"/>',
       f'<path d="M{x+w-4:.1f},{y:.1f} L{x+w:.1f},{y:.1f} L{x+w:.1f},{y+h:.1f} L{x+w-4:.1f},{y+h:.1f}" fill="none" stroke="{MAROON}" stroke-width="1.5"/>']
    for i in range(2):
        for j in range(2): g.append(f'<circle cx="{x+w*0.34+j*w*0.32:.1f}" cy="{y+h*0.33+i*h*0.36:.1f}" r="2.4" fill="{ROSE}"/>')
    return "".join(g)
def _mf_matpow(cx,cy,R): return _mf_mat(cx-R*0.18,cy,R*0.92)+_t(cx+R*0.72,cy-R*0.4,"n",10,MAROON,a="middle",it=True)
def _mf_det(cx,cy,R):
    return (_mf_mat(cx,cy,R)+f'<line x1="{cx-R*0.42:.1f}" y1="{cy-R*0.36:.1f}" x2="{cx+R*0.42:.1f}" y2="{cy+R*0.36:.1f}" stroke="{GRN}" stroke-width="1.2"/>'
            f'<line x1="{cx+R*0.42:.1f}" y1="{cy-R*0.36:.1f}" x2="{cx-R*0.42:.1f}" y2="{cy+R*0.36:.1f}" stroke="{ROSE}" stroke-width="1.2" stroke-dasharray="2 2"/>')
def _mf_rot(cx,cy,R):  # 旋轉 θ：原向量(藍)→旋轉後(栗)＋角弧箭頭
    o=(cx-R*0.15,cy+R*0.32); L=R*0.92; a0=math.radians(8); a1=math.radians(60)
    p1=(o[0]+L*math.cos(a0), o[1]-L*math.sin(a0)); p2=(o[0]+L*math.cos(a1), o[1]-L*math.sin(a1))
    g=[_vec(o,p1,"#9fbdd7"), _vec(o,p2,MAROON)]
    ar=R*0.46; aa0=(o[0]+ar*math.cos(a0), o[1]-ar*math.sin(a0)); aa1=(o[0]+ar*math.cos(a1), o[1]-ar*math.sin(a1))
    g.append(f'<path d="M{aa0[0]:.1f},{aa0[1]:.1f} A {ar:.1f} {ar:.1f} 0 0 0 {aa1[0]:.1f},{aa1[1]:.1f}" fill="none" stroke="{ROSE}" stroke-width="1.3"/>')
    tx,ty=-math.sin(a1),-math.cos(a1); bx,by=aa1[0]-6*tx, aa1[1]-6*ty; px,py=-ty,tx
    g.append(f'<polygon points="{aa1[0]:.1f},{aa1[1]:.1f} {bx+2.6*px:.1f},{by+2.6*py:.1f} {bx-2.6*px:.1f},{by-2.6*py:.1f}" fill="{ROSE}"/>')
    g.append(_t(o[0]+R*0.64, o[1]-R*0.26, "θ",6.5,ROSE,a="middle"))
    return "".join(g)

# ====== 數與式 ======
def _mf_sets(cx,cy,R):
    return (f'<rect x="{cx-R*0.95:.1f}" y="{cy-R*0.8:.1f}" width="{R*1.9:.1f}" height="{R*1.6:.1f}" rx="8" fill="#f4e6ec" stroke="{MAROON}" stroke-width="1.3"/>'
            f'<rect x="{cx-R*0.7:.1f}" y="{cy-R*0.6:.1f}" width="{R*1.4:.1f}" height="{R*1.2:.1f}" rx="7" fill="#e9d3dd" stroke="{ROSE}" stroke-width="1.1"/>'
            f'<rect x="{cx-R*0.42:.1f}" y="{cy-R*0.38:.1f}" width="{R*0.84:.1f}" height="{R*0.76:.1f}" rx="6" fill="#fff" stroke="{BLUE}" stroke-width="1.1"/>'
            +_t(cx-R*0.78,cy-R*0.46,"實",7.5,MAROON)+_t(cx,cy+R*0.04,"整",7.5,BLUE,a="middle"))
def _mf_abs(cx,cy,R):  # |x| = 原點 0 到 x 的距離
    oy=cy+R*0.18; ox=cx-R*0.5; xx=cx+R*0.55; ay=oy-R*0.5
    return "".join([
        f'<line x1="{cx-R:.1f}" y1="{oy:.1f}" x2="{cx+R:.1f}" y2="{oy:.1f}" stroke="#9aa6b2" stroke-width="1.4"/>',
        f'<line x1="{ox:.1f}" y1="{oy-4:.1f}" x2="{ox:.1f}" y2="{oy+4:.1f}" stroke="{INK}" stroke-width="1.4"/>'+_t(ox,oy+12,"0",7,INK,a="middle"),
        f'<circle cx="{xx:.1f}" cy="{oy:.1f}" r="2.6" fill="{ROSE}"/>'+_t(xx,oy+12,"x",7,ROSE,a="middle"),
        f'<line x1="{ox:.1f}" y1="{oy:.1f}" x2="{ox:.1f}" y2="{ay:.1f}" stroke="{MAROON}" stroke-width="0.6" stroke-dasharray="1.5 1.5"/>',
        f'<line x1="{xx:.1f}" y1="{oy:.1f}" x2="{xx:.1f}" y2="{ay:.1f}" stroke="{MAROON}" stroke-width="0.6" stroke-dasharray="1.5 1.5"/>',
        f'<line x1="{ox:.1f}" y1="{ay:.1f}" x2="{xx:.1f}" y2="{ay:.1f}" stroke="{MAROON}" stroke-width="1.1"/>',
        f'<polygon points="{ox:.1f},{ay:.1f} {ox+4:.1f},{ay-2:.1f} {ox+4:.1f},{ay+2:.1f}" fill="{MAROON}"/>',
        f'<polygon points="{xx:.1f},{ay:.1f} {xx-4:.1f},{ay-2:.1f} {xx-4:.1f},{ay+2:.1f}" fill="{MAROON}"/>',
        _t((ox+xx)/2,ay-2.5,"|x|",6.5,MAROON,a="middle")])
def _mf_sqrtline(cx,cy,R):
    g=[f'<line x1="{cx-R:.1f}" y1="{cy}" x2="{cx+R:.1f}" y2="{cy}" stroke="#9aa6b2" stroke-width="1.4"/>']
    for v,lab in [(-0.6,"1"),(0.6,"2")]:
        g.append(f'<line x1="{cx+v*R:.1f}" y1="{cy-4:.1f}" x2="{cx+v*R:.1f}" y2="{cy+4:.1f}" stroke="{INK}" stroke-width="1.2"/>'+_t(cx+v*R,cy+13,lab,8,INK,a="middle"))
    g.append(f'<circle cx="{cx+0.05*R:.1f}" cy="{cy:.1f}" r="2.6" fill="{ROSE}"/>')
    sv,_=_sqrt(cx-R*0.28,cy-9,"2",8,MAROON,True); g.append(sv)
    return "".join(g)
def _mf_amgm(cx,cy,R):
    return (f'<line x1="{cx-R:.1f}" y1="{cy+R*0.55:.1f}" x2="{cx+R:.1f}" y2="{cy+R*0.55:.1f}" stroke="#9aa6b2" stroke-width="1.2"/>'
            f'<rect x="{cx-R*0.7:.1f}" y="{cy-R*0.2:.1f}" width="{R*0.4:.1f}" height="{R*0.75:.1f}" fill="#f1d6df" stroke="{MAROON}" stroke-width="1"/>'
            f'<rect x="{cx+R*0.28:.1f}" y="{cy-R*0.55:.1f}" width="{R*0.4:.1f}" height="{R*1.1:.1f}" fill="#f1d6df" stroke="{MAROON}" stroke-width="1"/>'
            f'<line x1="{cx-R:.1f}" y1="{cy-R*0.05:.1f}" x2="{cx+R:.1f}" y2="{cy-R*0.05:.1f}" stroke="{ROSE}" stroke-width="1.3" stroke-dasharray="3 2"/>'
            +_t(cx-R*0.5,cy-R*0.3,"a",7,INK,a="middle")+_t(cx+R*0.48,cy-R*0.65,"b",7,INK,a="middle"))

# ================= 卡片＋通用開場 =================
def _card(X,Y,n,title,subt,stars,mini,core=False):
    fill=PINK if core else "#fff"; ring=MAROON if core else PINKB; rw=2.8 if core else 1.6
    g=[f'<rect x="{X+3}" y="{Y+4}" width="{CW}" height="{CH}" rx="16" fill="#e7cdc2" opacity="0.5"/>',
       f'<rect x="{X}" y="{Y}" width="{CW}" height="{CH}" rx="16" fill="{fill}" stroke="{ring}" stroke-width="{rw}"/>',
       _t(X+128,Y+26,title,13.5,MAROON,w=True,a="middle"), _t(X+128,Y+41,subt,9.5,MUTED,a="middle")]
    if core: g.append(_pill(X+212,Y+22,40,"核心"))
    elif stars: g.append(_stars(X+212,Y+25,stars))
    bx,by=X+46,Y+100
    g.append(f'<circle cx="{bx+1}" cy="{by+2}" r="33" fill="#e7cdc2" opacity="0.5"/><circle cx="{bx}" cy="{by}" r="33" fill="#fff" stroke="{MAROON}" stroke-width="2"/>')
    g.append(mini(bx,by,23)); g.append(_num(X+20,Y+20,n))
    return "".join(g)

def _opener(short, stations, sub="跟著心怡，照①→④順序，一張圖看懂整個單元"):
    AX,BX=168,452; TY,BY=74,248; pos=[(AX,TY),(BX,TY),(BX,BY),(AX,BY)]
    L=[f'<svg viewBox="0 0 {W} {H}" width="{W}" height="{H}" xmlns="http://www.w3.org/2000/svg" role="img" {_F}>',
       f'<rect x="3" y="3" width="{W-6}" height="{H-6}" rx="24" fill="{CREAM}" stroke="{CREAMB}" stroke-width="2"/>',
       _t(26,40,short+" ▸ 必考重點地圖",22,MAROON,w=True), _t(27,60,sub,12,MUTED), _t(W-22,40,"★ 越多＝越常考",11.5,GOLD,a="end"),
       _trail(AX+CW,TY+CH/2,BX,TY+CH/2,(AX+CW+BX)/2,TY+CH/2-16),
       _trail(BX+CW/2,TY+CH,BX+CW/2,BY,BX+CW/2+18,(TY+CH+BY)/2),
       _trail(BX,BY+CH/2,AX+CW,BY+CH/2,(AX+CW+BX)/2,BY+CH/2+16),
       _char(6,176,150,189)]
    for st,(X,Y) in zip(stations,pos):
        L.append(_card(X,Y,st["n"],st["title"],st["subt"],st.get("stars",0),st["mini"],st.get("core",False)))
        fx=X+84; rows=st["rows"]; ys={1:[106],2:[92,122],3:[80,106,132]}[len(rows)]
        for (toks,hi),ym in zip(rows,ys): L.append(_row(fx,Y+ym,toks,hi=hi))
    L.append("</svg>"); return "".join(L)

# ================= 三角（定案範本） =================
def _trig():
    AX,BX=168,452; TY,BY=74,248
    L=[f'<svg viewBox="0 0 {W} {H}" width="{W}" height="{H}" xmlns="http://www.w3.org/2000/svg" role="img" {_F}>',
       f'<rect x="3" y="3" width="{W-6}" height="{H-6}" rx="24" fill="{CREAM}" stroke="{CREAMB}" stroke-width="2"/>',
       _t(26,40,"三角 ▸ 必考重點地圖",22,MAROON,w=True), _t(27,60,"跟著心怡，照①→④順序，一張圖看懂整個單元",12,MUTED),
       _t(W-22,40,"★ 越多＝越常考",11.5,GOLD,a="end"),
       _trail(AX+CW,TY+CH/2,BX,TY+CH/2,(AX+CW+BX)/2,TY+CH/2-16),
       _trail(BX+CW/2,TY+CH,BX+CW/2,BY,BX+CW/2+18,(TY+CH+BY)/2),
       _trail(BX,BY+CH/2,AX+CW,BY+CH/2,(AX+CW+BX)/2,BY+CH/2+16),
       _char(6,176,150,189)]
    L.append(_card(AX,TY,"1","單位圓 · 三角比","基礎核心",0,_mf_unit,core=True)); fx=AX+84
    L.append(_row(fx,TY+80,[("t","sin θ ="),("f","y","r"),("t","， cos θ ="),("f","x","r")]))
    L.append(_row(fx,TY+106,[("t","tan θ ="),("f","sin θ","cos θ")]))
    L.append(_row(fx,TY+132,[("t","sin²θ + cos²θ = 1")],hi=True))
    L.append(_card(BX,TY,"2","正弦 · 餘弦定理","解三角形",2,_mf_tri)); fx=BX+84
    L.append(_t(fx,TY+84,"正弦",9.5,MUTED)); L.append(_sinelaw(fx+24,TY+80))
    L.append(_row(fx,TY+106,[("t","餘弦  c² = a² + b² − 2ab cos C")]))
    L.append(_row(fx,TY+132,[("t","面積  △ ="),("f","1","2"),("t","ab sin C")]))
    L.append(_card(BX,BY,"3","三角函數圖形","三角函數",3,_mf_sine)); fx=BX+84
    L.append(_row(fx,BY+80,[("t","y = a sin( bx + c ) + d")]))
    L.append(_row(fx,BY+106,[("t","週期 ="),("f","2π","b")],hi=True))
    L.append(_row(fx,BY+132,[("t","振幅 = | a |")],hi=True))
    L.append(_card(AX,BY,"4","倍角 · 疊合","三角函數 · 進階",3,_mf_super)); fx=AX+84
    L.append(_row(fx,BY+80,[("t","sin 2θ = 2 sin θ cos θ")]))
    L.append(_row(fx,BY+106,[("t","疊合：a sin x + b cos x")]))
    L.append(_row(fx,BY+132,[("t","="),("s","a²+b²"),("t","  · sin( x + φ )")],hi=True))
    L.append("</svg>"); return "".join(L)

